+#include <chrono>
+#include <cstdio>
+#include <cstdlib>
+namespace {
+void shortPhase(const char *Label) {
+  if (std::getenv("DTVM_TRACE_DIR")) std::fprintf(stderr, "SHORT_PHASE %s %llu\n", Label, (unsigned long long)std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now().time_since_epoch()).count());
+}
+struct ShortLifetime { ShortLifetime() { shortPhase("main-entry"); } ~ShortLifetime() { shortPhase("after-destruction"); } };
+}
 int exitMain(int ExitCode, Runtime *RT = nullptr) {
   if (RT) {
     RT->getStatistics().report();
@@ -160,6 +169,7 @@ static bool runEVMBenchmark(const std::string &Filename,
 #endif // ZEN_ENABLE_EVM

 int main(int argc, char *argv[]) {
