+  shortPhase("after-instance");
   if (!InstRet) {
     const Error &Err = InstRet.getError();
     ZEN_ASSERT(!Err.isEmpty());
@@ -607,6 +623,7 @@ int main(int argc, char *argv[]) {
   Inst->setCustomData((void *)EVMAbiMockCtx.get());
 #endif // ZEN_ENABLE_EVMABI_TEST

